(function(){
'use strict';
const $=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let D,state,selected=0,tmx=null,groupIndex=-1,filename='map.tmx';
const types=['basic','map_info','unitAdd','unitRemove','unitDetect','move','changeCredits','teamTags','teamTagDetect','team_info','mapText','objective','camera_start','camera_pan','rotate'];
const btn=(t,a,more='')=>`<button type="button" class="btn btn-small btn-plain" data-map="${a}" ${more}>${t}</button>`;
function blank(){return {width:1600,height:1000,objects:[{id:'1',name:'map_info',type:'map_info',x:0,y:0,width:80,height:50,properties:[{key:'type',value:'skirmish'}]},{id:'2',name:'reinforcements',type:'unitAdd',x:300,y:250,width:150,height:100,properties:[{key:'team',value:'0'},{key:'spawnUnits',value:'tank*2'},{key:'delay',value:'10s'}]}]};}
function persist(){try{localStorage.setItem('rwlab-map-project-v1',JSON.stringify(state));$('#map-status').textContent='已保存触发器草稿到本浏览器';}catch{$('#map-status').textContent='草稿未能保存，请导出 XML';}}
function mount(data){D=data;let handoff=null;try{handoff=sessionStorage.getItem('rwlab-map-language-handoff')}catch{}if(handoff){sessionStorage.removeItem('rwlab-map-language-handoff');const saved=JSON.parse(handoff);importMap(new File([saved.xml],saved.name,{type:'application/xml'}));return;}if(!state){try{const s=JSON.parse(localStorage.getItem('rwlab-map-project-v1'));if(!Array.isArray(s?.objects))throw Error();state=s;}catch{state=blank();}}render();}
function current(){return state.objects[selected];}
function propDef(key,type){return D.map.find(x=>x.key===key&&(x.scope.includes(type)||x.scope==='触发器通用'))||D.map.find(x=>x.key===key);}
function objectNode(o,doc){const el=doc.createElement('object');for(const key of ['id','name','type','x','y','width','height'])el.setAttribute(key,String(o[key]??''));if(o.extra)for(const [k,v] of Object.entries(o.extra))el.setAttribute(k,v);if(o.children){const parsed=new DOMParser().parseFromString('<root>'+o.children+'</root>','application/xml');for(const child of [...parsed.documentElement.childNodes])el.append(doc.importNode(child,true));}const props=doc.createElement('properties');for(const p of o.properties){props.append(doc.createComment(' '+(propDef(p.key,o.type)?.description_zh||'自定义属性').replace(/--/g,'—')+' '));const node=doc.createElement('property');node.setAttribute('name',p.key);if(p.type)node.setAttribute('type',p.type);node.setAttribute('value',p.value);props.append(node);}el.prepend(props);return el;}
function serialize(full=false){const doc=full&&tmx?new DOMParser().parseFromString(new XMLSerializer().serializeToString(tmx),'application/xml'):document.implementation.createDocument('','objectgroup');let group;if(full&&tmx){group=[...doc.querySelectorAll('objectgroup')][groupIndex];if(!group){group=doc.createElement('objectgroup');group.setAttribute('name','triggers');doc.documentElement.append(group);}for(const el of [...group.children])if(el.tagName==='object')el.remove();}else{group=doc.documentElement;group.setAttribute('name','triggers');}for(const o of state.objects)group.append(objectNode(o,doc));if(full&&tmx){const max=Math.max(0,...[...doc.querySelectorAll('object')].map(x=>Number(x.getAttribute('id'))||0));doc.documentElement.setAttribute('nextobjectid',String(max+1));}const xml=new XMLSerializer().serializeToString(doc).replace(/^<\?xml[^?]*\?>\s*/,'');return '<?xml version="1.0" encoding="UTF-8"?>\n'+xml;}
function checks(){const out=[],ids=new Set(),names=new Set();for(const o of state.objects){if(ids.has(o.id))out.push('重复对象 ID：'+o.id);ids.add(o.id);if(!o.name)out.push('存在空对象名称');if(names.has(o.name))out.push('名称重复，引用时请核对：'+o.name);names.add(o.name);const keys=new Set();for(const p of o.properties){if(keys.has(p.key))out.push(o.name+' 的属性重复：'+p.key);keys.add(p.key);}if(o.type==='unitAdd'&&!o.properties.some(p=>p.key==='spawnUnits'&&p.value))out.push(o.name+' 尚未填写 spawnUnits');}return out;}
function update(){const code=$('#map-code');if(!code)return;code.textContent=serialize(!!tmx);$('#map-checks').textContent=checks().join('；')||'✓ 对象结构检查通过';draw();persist();}
function render(){if(!location.hash.startsWith('#map-editor'))return;selected=Math.min(Math.max(0,selected),state.objects.length-1);const o=current();$('#main').innerHTML=`<div class="ed-shell map-shell">${RWEditor.editorHeader('map')}<div class="ed-toolbar"><strong>触发器工作台</strong><div class="ed-toolbar-actions"><label class="btn btn-small btn-plain ed-file-button">导入 TMX<input type="file" id="map-import" accept=".tmx,.xml"></label>${btn('新建片段','new')}${btn('导出 XML 片段','fragment')}<button class="btn btn-small btn-dark" data-map="export" ${tmx?'':'disabled'}>导出完整 TMX ↓</button></div><span id="map-status"></span></div><div class="ed-inline-note map-note">${tmx?'已导入 '+E(filename)+'，导出会保留原地图地块、其他图层和外部资源引用。':'当前是触发器片段。导入完整 TMX 后，可导出保留地图图层的文件。'} 画布显示触发区域与坐标；地块绘制请在 Tiled 中完成。</div><div class="map-layout"><aside class="ed-sidebar"><div class="ed-panel-title"><strong>触发对象 <span>${state.objects.length}</span></strong>${btn('＋','add')}</div><div class="ed-module-list">${state.objects.map((x,i)=>`<button class="ed-module ${i===selected?'active':''}" data-map="select" data-index="${i}"><span class="ed-module-symbol">⌖</span><span><strong>${E(x.name||'未命名')}</strong><small>${E(x.type)} · #${E(x.id)}</small></span></button>`).join('')}</div><div class="ed-sidebar-bottom"><p>选择一个触发对象，设置它何时启动、执行什么。可以为地图添加增援、任务目标或提示消息。</p><a href="#reference">地图完整参数索引 ↗</a></div></aside><section class="map-form"><div class="ed-panel-title"><strong>坐标总览</strong><span>点击空白处移动选中区域</span></div><div id="map-canvas"></div><div class="map-dimensions"><label>范围宽<input data-map-size="width" type="number" min="1" value="${state.width}"></label><label>范围高<input data-map-size="height" type="number" min="1" value="${state.height}"></label></div>${o?`<div class="ed-module-heading"><h2>触发区域 <span>/ ${E(o.name)}</span></h2>${btn('移除对象','delete')}</div><div class="ed-build-grid"><label>对象名称<input data-map-field="name" value="${E(o.name)}"></label><label>触发器类型<select data-map-field="type">${[...new Set([o.type,...types])].map(t=>`<option value="${E(t)}" ${t===o.type?'selected':''}>${({"basic":"基础触发器","map_info":"地图信息","unitAdd":"生成单位","unitRemove":"移除单位","unitDetect":"检测单位","move":"移动命令","changeCredits":"修改资金","teamTags":"修改队伍标签","teamTagDetect":"检测队伍标签","team_info":"队伍信息","mapText":"地图文字","objective":"任务目标","camera_start":"初始镜头","camera_pan":"镜头移动","rotate":"初始朝向"})[t]||t} · ${E(t)}</option>`).join('')}</select></label></div><div class="map-coordinates">${['x','y','width','height'].map(k=>`<label>${({x:'横坐标 X',y:'纵坐标 Y',width:'宽度',height:'高度'})[k]}<input data-map-field="${k}" type="number" value="${E(o[k])}" ${['width','height'].includes(k)?'min="0"':''}></label>`).join('')}</div><div class="ed-panel-title"><strong>对象属性</strong>${btn('＋ 添加属性','property')}</div>${o.properties.map((x,i)=>`<article class="ed-field"><div class="ed-field-header"><label>${E((RWI18n.lang==='en'?propDef(x.key,o.type)?.label_en:({team:'所属队伍',spawnUnits:'生成哪些单位',delay:'等待多久后触发',repeatDelay:'重复间隔',globalMessage:'提示消息',activatedBy:'由哪些触发器启动',activateIds:'同时启动的触发器',minUnits:'至少需要多少单位',maxUnits:'最多允许多少单位',winCondition:'胜利条件'})[x.key])||propDef(x.key,o.type)?.description_zh?.split(/[；，]/)[0]||'自定义属性')}</label><button class="ed-remove" data-map="remove-property" data-index="${i}" aria-label="移除属性 ${E(x.key)}">×</button></div><div class="ed-field-meta"><code>${E(x.key)}</code><span>${E(propDef(x.key,o.type)?.scope||'自定义')}</span></div><textarea data-map-property="${i}" rows="1" spellcheck="false" aria-label="${E(x.key)}">${E(x.value)}</textarea></article>`).join('')}`:'<div class="ed-empty">点击左侧 ＋ 新增触发对象。</div>'}</section><aside class="ed-output"><div class="ed-panel-title"><strong>${tmx?'完整 TMX':'触发器 XML'}</strong>${btn('复制','copy')}</div><pre id="map-code" tabindex="0"></pre><div class="ed-checks"><strong>静态检查</strong><p id="map-checks"></p><p class="ed-check-foot">浏览器会保存触发器草稿。导入的完整地图请及时导出备份，并在游戏中测试效果。</p></div></aside></div></div>`;update();}
function draw(){const el=$('#map-canvas');if(!el)return;const w=Math.max(1,Number(state.width)),h=Math.max(1,Number(state.height));el.innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${E(RWI18n.t('地图触发区域坐标预览'))}"><defs><pattern id="map-grid" width="${w/20}" height="${h/15}" patternUnits="userSpaceOnUse"><path d="M ${w/20} 0 L 0 0 0 ${h/15}" fill="none" stroke="#cad3c6" stroke-width="1"/></pattern></defs><rect width="${w}" height="${h}" fill="url(#map-grid)"/>${state.objects.map((o,i)=>`<g data-map="canvas-select" data-index="${i}" tabindex="0" role="button" aria-label="${E(RWI18n.t('选择')+' '+o.name)}"><rect x="${Number(o.x)}" y="${Number(o.y)}" width="${Math.max(12,Number(o.width))}" height="${Math.max(12,Number(o.height))}" fill="${selected===i?'#c66a2e66':'#53735f44'}" stroke="${selected===i?'#b75b29':'#3f5a46'}" stroke-width="${w/400}"/><text x="${Number(o.x)+6}" y="${Number(o.y)+22}" font-size="${Math.max(14,w/65)}" fill="#273c2d">${E(o.name)}</text></g>`).join('')}</svg>`;}
function propertyDialog(){const el=document.createElement('dialog');el.className='ed-dialog ed-wide';el.id='map-dialog';el.innerHTML=`<div class="ed-dialog-head"><h2>地图属性 · 中文命令目录</h2><button data-map="close" class="icon-btn" aria-label="关闭">×</button></div><div class="ed-dialog-body"><div class="ed-search-row"><input id="map-prop-search" placeholder="搜索名称、中文含义或适用对象" aria-label="搜索地图属性"><select id="map-prop-scope"><option value="current">当前对象常用属性</option><option value="all">全部 88 项属性</option></select></div><div id="map-prop-results"></div><details><summary>添加自定义属性</summary><label>原始属性名<input id="map-custom-name"></label><label>值<input id="map-custom-value"></label>${btn('添加','custom-property')}</details></div>`;document.body.append(el);el.showModal();el.addEventListener('close',()=>el.remove());renderProperties();}
function renderProperties(){const q=$('#map-prop-search').value.toLowerCase(),all=$('#map-prop-scope').value==='all',o=current();$('#map-prop-results').innerHTML=D.map.filter(x=>(all||x.scope==='触发器通用'||x.scope.includes(o.type)||x.scope==='多种对象')&&JSON.stringify(x).toLowerCase().includes(q)).map(x=>`<button class="ed-command-choice" data-map="choose-property" data-index="${D.map.indexOf(x)}" ${o.properties.some(p=>p.key===x.key)?'disabled':''}><strong>${E(x.description_zh)}</strong><span><code>${E(x.key)}</code><small>${E(x.scope)}</small></span></button>`).join('')||'<p>没有匹配属性。可切换到全部目录，确认适用范围后添加。</p>';}
async function importMap(file){if(file.size>20*1024*1024)throw Error('TMX 超过 20 MB');const text=await file.text();if(/<!DOCTYPE|<!ENTITY/i.test(text))throw Error('请使用没有外部实体声明的普通 TMX XML。');const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror'))throw Error('XML 格式不正确，无法导入。');const root=doc.documentElement;if(!['map','objectgroup'].includes(root.tagName))throw Error('请选择 TMX 地图或 objectgroup XML 片段。');const groups=root.tagName==='map'?[...doc.querySelectorAll('objectgroup')]:[root];const candidates=groups.map((g,i)=>({g,i})).filter(({g})=>g.getAttribute('name')==='triggers');if(candidates.length>1)throw Error('地图包含多个 triggers 对象组，请先在 Tiled 合并或改名后导入。');const found=candidates[0];let group=found?.g||(root.tagName==='objectgroup'?root:null);const objects=group?[...group.children].filter(x=>x.tagName==='object').map(el=>{const o={properties:[],extra:{}};for(const k of ['id','name','type','x','y','width','height'])o[k]=el.getAttribute(k)||(['x','y','width','height'].includes(k)?'0':'');if(!o.type)o.type=el.getAttribute('class')||'basic';for(const a of el.attributes)if(!['id','name','type','x','y','width','height'].includes(a.name))o.extra[a.name]=a.value;o.properties=[...el.querySelectorAll(':scope > properties > property')].map(p=>({key:p.getAttribute('name'),value:p.hasAttribute('value')?p.getAttribute('value'):p.textContent,type:p.getAttribute('type')||''}));o.children=[...el.childNodes].filter(n=>!(n.nodeType===1&&n.tagName==='properties')).map(n=>new XMLSerializer().serializeToString(n)).join('');return o;}):[];
 const mapWidth=(Number(root.getAttribute('width'))||100)*(Number(root.getAttribute('tilewidth'))||20),mapHeight=(Number(root.getAttribute('height'))||60)*(Number(root.getAttribute('tileheight'))||20);tmx=root.tagName==='map'?doc:null;groupIndex=found?.i??-1;filename=file.name;state={width:mapWidth,height:mapHeight,objects};selected=0;render();toast(tmx?'TMX 已导入，原地图图层会保留':'已导入 XML 片段');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-map]');if(!b)return;try{const a=b.dataset.map;if(a==='select'||a==='canvas-select'){selected=Number(b.dataset.index);render();return;}if(a==='add'){const max=Math.max(0,...state.objects.map(x=>Number(x.id)||0),...(tmx?[...tmx.querySelectorAll('object')].map(x=>Number(x.getAttribute('id'))||0):[]));state.objects.push({id:String(max+1),name:'trigger'+(max+1),type:'basic',x:100,y:100,width:100,height:100,properties:[]});selected=state.objects.length-1;render();}if(a==='delete'){state.objects.splice(selected,1);render();}if(a==='new'){state=blank();tmx=null;groupIndex=-1;selected=0;render();toast('已创建新的触发器片段');}if(a==='property')propertyDialog();if(a==='close')$('#map-dialog').close();if(a==='choose-property'){const def=D.map[Number(b.dataset.index)];current().properties.push({key:def.key,value:def.key==='delay'?'10s':''});renderProperties();render();}if(a==='custom-property'){const key=$('#map-custom-name').value.trim();if(!key||current().properties.some(x=>x.key===key))throw Error('请填写不重复的属性名');current().properties.push({key,value:$('#map-custom-value').value});$('#map-dialog').close();render();}if(a==='remove-property'){current().properties.splice(Number(b.dataset.index),1);render();}if(a==='fragment'||a==='export'){const text=serialize(a==='export');if(new DOMParser().parseFromString(text,'application/xml').querySelector('parsererror'))throw Error('导出 XML 结构检查失败，请检查属性内容。');const name=a==='export'?filename.replace(/\.xml$/i,'.tmx'):'map-triggers.xml';download(text,name,'application/xml;charset=utf-8');}if(a==='copy')await copy(serialize(!!tmx));}catch(err){toast(err.message);}});
document.addEventListener('click',e=>{const svg=e.target.closest('#map-canvas svg');if(!svg||e.target.closest('[data-map]')||!current())return;const rect=svg.getBoundingClientRect();const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const pos=point.matrixTransform(svg.getScreenCTM().inverse());current().x=Math.round(Math.max(0,Math.min(state.width,pos.x)));current().y=Math.round(Math.max(0,Math.min(state.height,pos.y)));render();});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='map-prop-search')renderProperties();if(el.dataset.mapField){const k=el.dataset.mapField;current()[k]=['x','y','width','height'].includes(k)?Number(el.value)||0:el.value;update();}if(el.dataset.mapProperty!==undefined){current().properties[Number(el.dataset.mapProperty)].value=el.value;update();}});
document.addEventListener('change',async e=>{try{const el=e.target;if(el.id==='map-prop-scope')renderProperties();if(el.dataset.mapField==='type')render();if(el.dataset.mapSize){state[el.dataset.mapSize]=Math.max(1,Number(el.value)||1);update();}if(el.id==='map-import'&&el.files[0])await importMap(el.files[0]);}catch(err){toast(err.message);}});
window.addEventListener('rw-before-language-change',event=>{if(tmx)try{sessionStorage.setItem('rwlab-map-language-handoff',JSON.stringify({xml:serialize(true),name:filename}))}catch{event.preventDefault();toast('地图较大，请先导出完整地图备份，再切换语言。');}});
window.RWMap={mount,dispose(){document.querySelector('#map-dialog')?.remove();},serialize,importMap};
})();
